from auto_config.generator.gnb.managed_objects.managed_object import ManagedObject


class BbcapParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        if 'TDD' in execution_config['duplex_mode']:
            self.set_parameter('smodBoardConfigType', 'NRTDD')
        else:
            self.set_parameter('smodBoardConfigType', 'NRFDD')
